children = {
    "A": ["B", "C"],
    "B": ["D", "E"],
    "C": [], "D": [], "E": []
}

def height(node):
    if node is None:
        return -1
    longest_child = -1
    for child in children[node]:
        longest_child = max(longest_child, height(child))
    return 1 + longest_child

print(height("A"))
print(height("B"))
print(height("E"))
print(height(None))

def tree_height(children, root):
    if root is None:
        return -1
    height = 0
    stack = [(root, 0)]
    while stack:
        node, depth = stack.pop()
        height = max(height, depth)
        for child in children[node]:
            stack.append((child, depth + 1))
    return height

children = {"A": ["B", "C"], "B": ["D"], "C": [], "D": []}

print(tree_height(children, "A"))
print(tree_height(children, "C"))
print(tree_height({}, None))

def depth_of(parent, node):
    if node not in parent:
        raise ValueError("unknown node")
    depth = 0
    while parent[node] is not None:
        node = parent[node]
        depth += 1
    return depth

parent = {"A": None, "B": "A", "C": "B"}

print(depth_of(parent, "C"))
print(depth_of(parent, "A"))
try:
    depth_of({}, "A")
except ValueError:
    print("ValueError")

def leaf_ids(children, root):
    if root is None:
        return []
    leaves = []
    stack = [root]
    while stack:
        node = stack.pop()
        if not children[node]:
            leaves.append(node)
        else:
            for child in reversed(children[node]):
                stack.append(child)
    return leaves

children = {"A": ["B", "C"], "B": ["D", "E"], "C": [], "D": [], "E": []}

print(leaf_ids(children, "A"))
print(leaf_ids(children, "C"))
print(leaf_ids({}, None))
